6	)
7	
8	// 竞争候选只包含账户连续交易的最前面一笔并胜出时：
9	// 只有该笔随胜出候选确认，落选本地提议中的其余交易回到排队，
10	// 与从未打包的交易一起按账户序号在下一轮正常打包。
11	//
12	// 场景固定为：四名验证者、单块最多三笔、交易池不限容量。
13	// 账户序号 1、2 先正常确认；随后提交序号 3、4、5、6（费用 10、1、100、200，
14	// 到期轮次足够远）。本地提议为 [3 4 5]，6 留在池中；再登记只含 3 的竞争候选。
15	// 竞争候选两票时一切不变，第三票胜出后仅 3 确认一次，4、5 回到 queued，
16	// 与 6 一起按 4、5、6 等待打包；下一轮本地提议依次为 [4 5 6]。
17	func TestCompetingCandidateConfirmRequeuesRemaining(t *testing.T) {
18		keys := genKeys(t, 4)
19		n, _ := newTestNode(t, keys, 3) // 单块上限 3，池容量 0 表示不限制
20		sender := keys[0]               // 发送者同时是验证者不影响本场景
21	
22		// 前两轮：序号 1、2 各自随本地提议正常确认，确认历史推进到高度 2。
23		tx1 := NewTransaction(sender.priv, 1, []byte("tx-1"), 5, 1000)
24		tx2 := NewTransaction(sender.priv, 2, []byte("tx-2"), 5, 1000)
25		for _, tx := range []*Transaction{tx1, tx2} {
26			if _, err := n.Submit(tx); err != nil {
27				t.Fatalf("submit seq %d: %v", tx.Sequence, err)
28			}
29			local, err := n.Propose()
30			if err != nil {
31				t.Fatal(err)
32			}
33			if fmt.Sprint(local.TxIDs) != fmt.Sprint([]string{tx.ID()}) {
34				t.Fatalf("setup round %d: local proposal = %v, want [%s]", n.CurrentRound(), local.TxIDs, tx.ID())
35			}
36			confirmCandidate(t, n, keys, local.BlockID)
37		}
38		if n.CurrentRound() != 3 || n.Height() != 2 {
39			t.Fatalf("setup: round=%d height=%d, want 3/2", n.CurrentRound(), n.Height())
40		}
41		block1, err := n.BlockAt(1)
42		if err != nil {
43			t.Fatal(err)
44		}
45		block2, err := n.BlockAt(2)
46		if err != nil {
47			t.Fatal(err)
48		}
49		if block2.PreviousID != block1.ID {
50			t.Fatalf("setup: block2 previous = %q, want %q", block2.PreviousID, block1.ID)
51		}
52	
53		// 提交序号 3、4、5、6：费用 10、1、100、200，到期轮次足够远。
54		tx3 := NewTransaction(sender.priv, 3, []byte("tx-3"), 10, 1000)
55		tx4 := NewTransaction(sender.priv, 4, []byte("tx-4"), 1, 1000)
56		tx5 := NewTransaction(sender.priv, 5, []byte("tx-5"), 100, 1000)
57		tx6 := NewTransaction(sender.priv, 6, []byte("tx-6"), 200, 1000)
58		for _, tx := range []*Transaction{tx3, tx4, tx5, tx6} {
59			if _, err := n.Submit(tx); err != nil {
60				t.Fatalf("submit seq %d: %v", tx.Sequence, err)
61			}
62		}
63		id3, id4, id5, id6 := tx3.ID(), tx4.ID(), tx5.ID(), tx6.ID()
64	
65		// 本地提议按账户序号依次包含 3、4、5；费用更高的 6 因单块上限留在池中排队。
66		local, err := n.Propose()
67		if err != nil {
68			t.Fatal(err)
69		}
70		if local.Round != 3 || local.Empty {
71			t.Fatalf("local proposal view wrong: %+v", local)
72		}
73		if fmt.Sprint(local.TxIDs) != fmt.Sprint([]string{id3, id4, id5}) {
74			t.Fatalf("local proposal = %v, want [3 4 5] by account sequence", local.TxIDs)
75		}
76		for _, id := range []string{id3, id4, id5} {
77			if info, _ := n.Tx(id); info.Status != StatusProposed {
78				t.Fatalf("tx %s status = %s, want proposed", id, info.Status)
79			}
80		}
81		if info, _ := n.Tx(id6); info.Status != StatusQueued {
82			t.Fatalf("tx 6 status = %s, want queued (block limit 3)", info.Status)
83		}
84	
85		// 登记只含 3 的竞争候选。
86		altID := registerMust(t, n, 3, []string{id3})
87		if altID == local.BlockID {
88			t.Fatal("test setup: competing candidate must differ from local proposal")
89		}
90	
91		// 竞争候选取得两票（4 人名单需严格超过 2 票）时仍未确认：
92		// 轮次、确认高度、已有确认历史与账户已确认序号都不改变，
93		// 3、4、5 继续等待投票，6 继续等待打包。
94		for i := 0; i < 2; i++ {
95			res, err := n.Vote(keys[i].pub, 3, altID)
96			if err != nil || !res.Counted || res.Confirmed || res.Block != nil {
97				t.Fatalf("alt vote %d must count without confirming: %+v %v", i+1, res, err)
98			}
99		}
100		if n.CurrentRound() != 3 || n.Height() != 2 {
101			t.Fatalf("before quorum round=%d height=%d, want 3/2", n.CurrentRound(), n.Height())
102		}
103		if latest, ok := n.LatestBlock(); !ok || latest.ID != block2.ID {
104			t.Fatalf("latest block before quorum = %+v, want height-2 block %s", latest, block2.ID)
105		}
106		for h, want := range map[uint64]string{1: block1.ID, 2: block2.ID} {
107			blk, err := n.BlockAt(h)
108			if err != nil || blk.ID != want {
109				t.Fatalf("confirmed history at height %d changed before quorum: %+v", h, blk)
110			}
111		}
112		acct := n.Account(sender.pub)
113		if acct.ConfirmedSequence != 2 {
114			t.Fatalf("confirmed sequence = %d, want 2 before quorum", acct.ConfirmedSequence)
115		}
116		assertPending(t, acct, []string{id3, id4, id5, id6}, []string{"waiting-vote", "waiting-vote", "waiting-vote", "waiting-pack"})
117		altView := findCandidate(t, n, 3, altID)
118		localView := findCandidate(t, n, 3, local.BlockID)
119		if altView.Result != CandidatePending || len(altView.Voters) != 2 {
120			t.Fatalf("alt candidate wrong before quorum: %+v", altView)
121		}
122		if localView.Result != CandidatePending {
123			t.Fatalf("local candidate must stay pending before quorum: %+v", localView)
124		}
125	
126		// 第三票使竞争候选胜出：本轮只新增该候选的一条确认记录，交易列表仅有 3，
127		// 前块标识接在此前的最新确认块（高度 2）之后。
128		res, err := n.Vote(keys[2].pub, 3, altID)
129		if err != nil || !res.Counted || !res.Confirmed || res.Block == nil {
130			t.Fatalf("third alt vote should confirm: %+v %v", res, err)
131		}
132		if res.Block.Height != 3 || res.Block.Round != 3 || res.Block.ID != altID {
133			t.Fatalf("confirming block wrong: %+v", res.Block)
134		}
135		if fmt.Sprint(res.Block.TxIDs) != fmt.Sprint([]string{id3}) {
136			t.Fatalf("confirming block txs = %v, want [3]", res.Block.TxIDs)
137		}
138		if res.Block.PreviousID != block2.ID {
139			t.Fatalf("confirming block previous = %q, want latest confirmed %q", res.Block.PreviousID, block2.ID)
140		}
141		if n.CurrentRound() != 4 || n.Height() != 3 {
142			t.Fatalf("after confirm round=%d height=%d, want 4/3", n.CurrentRound(), n.Height())
143		}
144		if latest, _ := n.LatestBlock(); latest.ID != altID {
145			t.Fatalf("latest block = %q, want winning candidate %q", latest.ID, altID)
146		}
147	
148		// 共享的 3 只确认一次：关联胜出候选的区块标识与高度，账户已确认序号只推进到 3。
149		info3, err := n.Tx(id3)
150		if err != nil {
151			t.Fatal(err)
152		}
153		if info3.Status != StatusConfirmed || info3.BlockHeight != 3 || info3.BlockID != altID {
154			t.Fatalf("shared tx 3 must confirm exactly once with winner block: %+v", info3)
155		}
156		acct = n.Account(sender.pub)
157		if acct.ConfirmedSequence != 3 {
158			t.Fatalf("confirmed sequence = %d, want exactly 3", acct.ConfirmedSequence)
159		}
160	
161		// 4、5 虽曾进入落选的本地提议，也应回到 queued，与原先未打包的 6 一起
162		// 按 4、5、6 留在账户待处理列表，说明均为 waiting-pack，缺口为 0。
163		assertPending(t, acct, []string{id4, id5, id6}, []string{"waiting-pack", "waiting-pack", "waiting-pack"})
164	
165		// 回到排队的交易不带确认块关联，保留原始交易内容与有效签名。
166		for _, tx := range []*Transaction{tx4, tx5, tx6} {
167			info, err := n.Tx(tx.ID())
168			if err != nil {
169				t.Fatal(err)
170			}
171			if info.Status != StatusQueued || info.BlockHeight != 0 || info.BlockID != "" {
172				t.Fatalf("requeued tx %d must not carry block association: %+v", tx.Sequence, info)
173			}
174			if info.Tx == nil || !info.Tx.Verify() {
175				t.Fatalf("requeued tx %d must keep a valid signature: %+v", tx.Sequence, info.Tx)
176			}
177			if fmt.Sprintf("%x", info.Tx.Signature) != fmt.Sprintf("%x", tx.Signature) ||
178				fmt.Sprintf("%x", info.Tx.Content) != fmt.Sprintf("%x", tx.Content) ||
179				info.Tx.Fee != tx.Fee || info.Tx.Expiry != tx.Expiry {
180				t.Fatalf("requeued tx %d content changed: %+v, want original %+v", tx.Sequence, info.Tx, tx)
181			}
182		}
183	
184		// 旧轮候选查询：本地提议落选、竞争候选胜出，各自保留原来的交易顺序。
185		rc, err := n.Candidates(3)
186		if err != nil {
187			t.Fatal(err)
188		}
189		if !rc.Ended || rc.UnconfirmedEnd {
190			t.Fatalf("round 3 record wrong after confirm: %+v", rc)
191		}
192		localView = findCandidate(t, n, 3, local.BlockID)
193		altView = findCandidate(t, n, 3, altID)
194		if localView.Result != CandidateLost || !localView.Local ||
195			fmt.Sprint(localView.TxIDs) != fmt.Sprint([]string{id3, id4, id5}) {
196			t.Fatalf("local candidate must be lost with original order [3 4 5]: %+v", localView)
197		}
198		if altView.Result != CandidateWon || altView.Local ||
199			fmt.Sprint(altView.TxIDs) != fmt.Sprint([]string{id3}) {
200			t.Fatalf("alt candidate must be won with original order [3]: %+v", altView)
201		}
202	
203		// 读取历史记录不能使已经回到排队的交易重新等待投票。
204		for _, id := range []string{id4, id5, id6} {
205			if info, _ := n.Tx(id); info.Status != StatusQueued {
206				t.Fatalf("reading history re-proposed tx %s: status = %s, want queued", id, info.Status)
207			}
208		}
209	
210		// 下一轮：本地提议依次包含 4、5、6。费用更高的 5、6 不能越过 4 排在前面，
211		// 已确认的 3 不能再次入选，4、5 也不因曾属于落选候选而被漏掉。
212		next, err := n.Propose()
213		if err != nil {
214			t.Fatal(err)
215		}
216		if next.Round != 4 || fmt.Sprint(next.TxIDs) != fmt.Sprint([]string{id4, id5, id6}) {
217			t.Fatalf("next round proposal = %v (round %d), want [4 5 6] in round 4", next.TxIDs, next.Round)
218		}
219	
220		// 产生新提议只让余下交易转为等待投票：账户已确认序号仍为 3，
221		// 已有确认块与旧轮候选结果保持原样。
222		acct = n.Account(sender.pub)
223		if acct.ConfirmedSequence != 3 {
224			t.Fatalf("confirmed sequence = %d after new proposal, want 3", acct.ConfirmedSequence)
225		}
226		assertPending(t, acct, []string{id4, id5, id6}, []string{"waiting-vote", "waiting-vote", "waiting-vote"})
227		if n.CurrentRound() != 4 || n.Height() != 3 {
228			t.Fatalf("after new proposal round=%d height=%d, want 4/3", n.CurrentRound(), n.Height())
229		}
230		for h, want := range map[uint64]string{1: block1.ID, 2: block2.ID, 3: altID} {
231			blk, err := n.BlockAt(h)
232			if err != nil || blk.ID != want {
233				t.Fatalf("confirmed history at height %d changed after new proposal: %+v", h, blk)
234			}
235		}
236		localView = findCandidate(t, n, 3, local.BlockID)
237		altView = findCandidate(t, n, 3, altID)
238		if localView.Result != CandidateLost || altView.Result != CandidateWon {
239			t.Fatalf("round 3 results changed after new proposal: local=%s alt=%s", localView.Result, altView.Result)
240		}
241	}
242	
243	// assertPending 断言账户待处理列表恰好为给定交易标识顺序，
244	// 每笔说明与 wantNotes 一一对应，且序号缺口为 0。
245	func assertPending(t *testing.T, acct *AccountInfo, wantIDs, wantNotes []string) {
246		t.Helper()
247		if len(acct.Pending) != len(wantIDs) {
248			t.Fatalf("pending = %d entries, want %d: %+v", len(acct.Pending), len(wantIDs), acct.Pending)
249		}
250		for i, info := range acct.Pending {
251			if info.ID != wantIDs[i] || info.Note != wantNotes[i] {
252				t.Fatalf("pending[%d] = (%s, %s), want (%s, %s)", i, info.ID, info.Note, wantIDs[i], wantNotes[i])
253			}
254		}
255		if acct.Gap != 0 {
256			t.Fatalf("gap = %d, want 0 (sequences consecutive)", acct.Gap)
257		}
258	}
259

