36	// seqScene 收拢“账户序号规则”场景的关键句柄。
37	type seqScene struct {
38		block1 Block
39		local  ProposalView
40		alt1ID string
41		// a3、a4、b2、c1 被本地提议引用：等待投票。
42		a3 *Transaction
43		a4 *Transaction
44		b2 *Transaction
45		c1 *Transaction
46		// b3 在本地提议冻结后才提交，仅排队；新候选首次引用它。
47		b3 *Transaction
48		// c2 仅被既有竞争候选 alt1 引用：等待投票。
49		c2 *Transaction
50		// list 是待登记的竞争候选列表，顺序与本地提议不同。
51		list []string
52	}
