54	// buildSeqScene 构造第 2 轮未决场景：确认历史使账户 A/B/C 的已确认序号为
55	// 2/1/0；本地提议 [a3, b2, c1, a4]；b3、c2 仅排队；alt1=[c2] 持一票。
56	func buildSeqScene(t *testing.T, n *Node, keys []testKey) seqScene {
57		t.Helper()
58		// 第 1 轮：确认 a1、a2、b1，推进已确认序号 A=2、B=1，C 保持 0。
59		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 10, 100)
60		a2 := NewTransaction(keys[0].priv, 2, []byte("a2"), 10, 100)
61		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 10, 100)
62		for _, tx := range []*Transaction{a1, a2, b1} {
63			if _, err := n.Submit(tx); err != nil {
64				t.Fatalf("setup submit %q: %v", tx.Content, err)
65			}
66		}
67		p1, err := n.Propose()
68		if err != nil {
69			t.Fatal(err)
70		}
71		confirmByVotes(t, n, keys, p1.BlockID)
72		if n.CurrentRound() != 2 || n.Height() != 1 {
73			t.Fatalf("setup: round=%d height=%d, want 2/1", n.CurrentRound(), n.Height())
74		}
75		block1, ok := n.LatestBlock()
76		if !ok || block1.Height != 1 {
77			t.Fatalf("setup: latest block = %+v ok=%v, want height 1", block1, ok)
78		}
79		for i, want := range []uint64{2, 1, 0} {
80			if got := n.Account(keys[i].pub).ConfirmedSequence; got != want {
81				t.Fatalf("setup: account %d confirmed sequence = %d, want %d", i, got, want)
82			}
83		}
84	
85		// 第 2 轮：a3、a4、b2、c1 在本地提议前提交，按费用被打包进提议。
86		a3 := NewTransaction(keys[0].priv, 3, []byte("a3"), 50, 100)
87		a4 := NewTransaction(keys[0].priv, 4, []byte("a4"), 10, 100)
88		b2 := NewTransaction(keys[1].priv, 2, []byte("b2"), 40, 100)
89		c1 := NewTransaction(keys[2].priv, 1, []byte("c1"), 20, 100)
90		for _, tx := range []*Transaction{a3, a4, b2, c1} {
91			if _, err := n.Submit(tx); err != nil {
92				t.Fatalf("setup submit %q: %v", tx.Content, err)
93			}
94		}
95		local, err := n.Propose()
96		if err != nil {
97			t.Fatal(err)
98		}
99		wantLocal := []string{a3.ID(), b2.ID(), c1.ID(), a4.ID()}
100		if fmt.Sprint(local.TxIDs) != fmt.Sprint(wantLocal) {
101			t.Fatalf("setup: local proposal = %v, want %v", local.TxIDs, wantLocal)
102		}
103	
104		// 提议冻结后才提交的交易仅在池中排队，不被本地提议引用。
105		b3 := NewTransaction(keys[1].priv, 3, []byte("b3"), 30, 100)
106		c2 := NewTransaction(keys[2].priv, 2, []byte("c2"), 15, 100)
107		for _, tx := range []*Transaction{b3, c2} {
108			if _, err := n.Submit(tx); err != nil {
109				t.Fatalf("setup submit %q: %v", tx.Content, err)
110			}
111			if info := n.mustTx(t, tx.ID()); info.Status != StatusQueued {
112				t.Fatalf("setup: %q status = %s, want queued", tx.Content, info.Status)
113			}
114		}
115	
116		// 既有竞争候选引用本地提议的 c1 与排队交易 c2（C 的序号自 1 起连续），
117		// 并持有一张未达门槛的票；c2 由此只被既有候选引用。
118		alt1, err := n.RegisterCandidate(2, []string{c1.ID(), c2.ID()})
119		if err != nil {
120			t.Fatal(err)
121		}
122		if alt1.Existing || alt1.BlockID == local.BlockID {
123			t.Fatalf("setup: alt1 must be a fresh candidate: %+v local=%s", alt1, local.BlockID)
124		}
125		if res, err := n.Vote(keys[0].pub, 2, alt1.BlockID); err != nil || !res.Counted || res.Confirmed {
126			t.Fatalf("setup vote for alt1: %+v %v", res, err)
127		}
128	
129		// 新候选列表：相邻交易来自不同账户，费用不按本地打包顺序排列，
130		// 但每个账户自己的序号从已确认序号加一起连续。
131		list := []string{b2.ID(), a3.ID(), c1.ID(), b3.ID(), a4.ID()}
132		return seqScene{
133			block1: block1,
134			local:  local,
135			alt1ID: alt1.BlockID,
136			a3:     a3,
137			a4:     a4,
138			b2:     b2,
139			c1:     c1,
140			b3:     b3,
141			c2:     c2,
142			list:   list,
143		}
