198	// TestRegisterCandidateInterleavedSequences 钉住接受路径：当前轮次已有本地
199	// 提议且尚未确认时，调用者可以登记与本地提议顺序不同的交易列表——各账户
200	// 已确认序号不同（2/1/0，至少一个非零），相邻交易来自不同账户、费用不按
201	// 本地打包顺序排列，只要各账户自己的序号连续就必须成功；查询保留调用者
202	// 给出的完整顺序，本地提议冻结，登记不推进序号也不产生确认块，只有新候选
203	// 实际引用的排队交易才转为等待投票。
204	func TestRegisterCandidateInterleavedSequences(t *testing.T) {
205		keys := genKeys(t, 4)
206		n, _ := newTestNode(t, keys, 5)
207		sc := buildSeqScene(t, n, keys)
208	
209		// 候选接在最新确认块之后：轮次 2、高度 2、前块为第 1 轮确认块。
210		wantID := BlockID(2, 2, sc.block1.ID, sc.list)
211		if wantID == sc.local.BlockID || wantID == sc.alt1ID {
212			t.Fatal("setup: new candidate id must differ from both existing candidates")
213		}
214		res, err := n.RegisterCandidate(2, sc.list)
215		if err != nil {
216			t.Fatalf("interleaved candidate with per-account consecutive sequences must register: %v", err)
217		}
218		if res.Existing {
219			t.Fatal("the new list must register as a fresh candidate, not an existing one")
220		}
221		if res.BlockID != wantID {
222			t.Fatalf("block id = %s, want %s (round 2, height 2, prev %s, caller order)",
223				res.BlockID, wantID, sc.block1.ID)
224		}
225	
226		// 登记不推进轮次与确认高度，也不产生确认块。
227		if n.CurrentRound() != 2 || n.Height() != 1 {
228			t.Fatalf("round=%d height=%d, want 2/1 (register must not confirm)", n.CurrentRound(), n.Height())
229		}
230		if _, err := n.BlockAt(2); reason(err) != ReasonUnknownBlock {
231			t.Fatalf("block at height 2: %v, want %s", err, ReasonUnknownBlock)
232		}
233		latest, ok := n.LatestBlock()
234		if !ok || latest.ID != sc.block1.ID {
235			t.Fatalf("latest block changed: %+v ok=%v, want %s", latest, ok, sc.block1.ID)
236		}
237	
238		// 本地提议保持原来的标识与顺序。
239		p, ok := n.Proposal()
240		if !ok || p.BlockID != sc.local.BlockID || fmt.Sprint(p.TxIDs) != fmt.Sprint(sc.local.TxIDs) {
241			t.Fatalf("local proposal changed: %+v ok=%v, want %+v", p, ok, sc.local)
242		}
243	
244		// 按轮次查询：新候选保留调用者给出的完整交易顺序，不按账户、序号或
245		// 费用重排；本地提议与既有候选及其票数不变。
246		rc, err := n.Candidates(2)
247		if err != nil {
248			t.Fatal(err)
249		}
250		if rc.Ended || !rc.HasRecords || len(rc.Candidates) != 3 {
251			t.Fatalf("round 2 must have exactly three pending candidates: %+v", rc)
252		}
253		var gotLocal, gotAlt, gotNew *CandidateView
254		for i := range rc.Candidates {
255			switch rc.Candidates[i].BlockID {
256			case sc.local.BlockID:
257				gotLocal = &rc.Candidates[i]
258			case sc.alt1ID:
259				gotAlt = &rc.Candidates[i]
260			case wantID:
261				gotNew = &rc.Candidates[i]
262			}
263		}
264		if gotLocal == nil || gotAlt == nil || gotNew == nil {
265			t.Fatalf("all three candidates must be present: %+v", rc.Candidates)
266		}
267		if gotNew.Local || gotNew.Result != CandidatePending || len(gotNew.Voters) != 0 {
268			t.Fatalf("new candidate must be a non-local pending candidate with no votes: %+v", gotNew)
269		}
270		if fmt.Sprint(gotNew.TxIDs) != fmt.Sprint(sc.list) {
271			t.Fatalf("candidate tx order = %v, want the exact caller order %v", gotNew.TxIDs, sc.list)
272		}
273		if !gotLocal.Local || fmt.Sprint(gotLocal.TxIDs) != fmt.Sprint(sc.local.TxIDs) || len(gotLocal.Voters) != 0 {
274			t.Fatalf("local candidate changed: %+v", gotLocal)
275		}
276		if len(gotAlt.Voters) != 1 || fmt.Sprintf("%x", gotAlt.Voters[0]) != fmt.Sprintf("%x", keys[0].pub) {
277			t.Fatalf("existing competitor lost its vote: %+v", gotAlt)
278		}
279	
280		// 登记不推进任何账户的已确认序号；新候选实际引用的排队交易 b3 才转为
281		// 等待投票，已有候选引用的交易（含 alt1 独有的 c2）继续保持等待投票。
282		assertAccountQueue(t, n, keys[0].pub, 2, map[string]string{
283			sc.a3.ID(): "waiting-vote", sc.a4.ID(): "waiting-vote",
284		})
285		assertAccountQueue(t, n, keys[1].pub, 1, map[string]string{
286			sc.b2.ID(): "waiting-vote", sc.b3.ID(): "waiting-vote",
287		})
288		assertAccountQueue(t, n, keys[2].pub, 0, map[string]string{
289			sc.c1.ID(): "waiting-vote", sc.c2.ID(): "waiting-vote",
290		})
291		if info := n.mustTx(t, sc.b3.ID()); info.Status != StatusProposed {
292			t.Fatalf("newly referenced b3 status = %s, want proposed", info.Status)
293		}
294		if info := n.mustTx(t, sc.c2.ID()); info.Status != StatusProposed {
295			t.Fatalf("c2 referenced by the earlier candidate must stay proposed, got %s", info.Status)
296		}
297	}
