299	// TestRegisterCandidateSequenceGapRejections 钉住拒绝路径：前序交易在池中
300	// （甚至已被本地提议引用）但候选跳过它，或同一账户的连续序号在列表中倒序
301	// 出现，都必须以 sequence-not-consecutive 拒绝；这些列表满足其他登记条件，
302	// 拒绝后候选集合、本地提议、既有候选票数与两类交易的状态全部保持原样。
303	func TestRegisterCandidateSequenceGapRejections(t *testing.T) {
304		keys := genKeys(t, 4)
305		n, _ := newTestNode(t, keys, 5)
306		sc := buildSeqScene(t, n, keys)
307	
308		// 额外的排队交易：a5 的前序 a4 已被本地提议引用，b4 的前序 b3 仅在池中排队。
309		a5 := NewTransaction(keys[0].priv, 5, []byte("a5"), 5, 100)
310		b4 := NewTransaction(keys[1].priv, 4, []byte("b4"), 5, 100)
311		for _, tx := range []*Transaction{a5, b4} {
312			if _, err := n.Submit(tx); err != nil {
313				t.Fatalf("setup submit %q: %v", tx.Content, err)
314			}
315		}
316	
317		cases := []struct {
318			name string
319			list []string
320		}{
321			// 前序交易 a3 在池中且已被本地提议引用，候选却从更后的序号 4 开始。
322			{"start beyond needed predecessor", []string{sc.a4.ID()}},
323			// 前序交易 a4 在池中且已被本地提议引用，候选中途跳过它。
324			{"skip proposed predecessor mid-list", []string{sc.a3.ID(), a5.ID()}},
325			// 前序交易 b3 仍在池中排队，候选中途跳过它。
326			{"skip queued predecessor mid-list", []string{sc.b2.ID(), b4.ID()}},
327			// A 的连续序号都在列表里，但 4 先于 3 出现；B、C 夹在中间不能掩盖倒序。
328			{"reversed order within one account", []string{sc.b2.ID(), sc.a4.ID(), sc.c1.ID(), sc.a3.ID()}},
329		}
330		for _, tc := range cases {
331			// 列表均不超单块上限、无未知或重复交易、全部在池中：
332			// 拒绝原因必须是序号不连续，而不是其他登记条件。
333			if _, err := n.RegisterCandidate(2, tc.list); reason(err) != ReasonSequenceGap {
334				t.Fatalf("%s: got %v, want %s", tc.name, err, ReasonSequenceGap)
335			}
336		}
337	
338		// 全部拒绝后：候选集合、本地提议与既有候选票数保持原样。
339		assertSeqRoundStable(t, n, sc, keys)
340	
341		// 原本只在排队的交易仍显示等待打包，不因失败登记被锁定；
342		// 原本等待投票的交易也不能被解锁；已确认序号不推进。
343		assertAccountQueue(t, n, keys[0].pub, 2, map[string]string{
344			sc.a3.ID(): "waiting-vote", sc.a4.ID(): "waiting-vote", a5.ID(): "waiting-pack",
345		})
346		assertAccountQueue(t, n, keys[1].pub, 1, map[string]string{
347			sc.b2.ID(): "waiting-vote", sc.b3.ID(): "waiting-pack", b4.ID(): "waiting-pack",
348		})
349		assertAccountQueue(t, n, keys[2].pub, 0, map[string]string{
350			sc.c1.ID(): "waiting-vote", sc.c2.ID(): "waiting-vote",
351		})
352		for _, tx := range []*Transaction{sc.b3, a5, b4} {
353			if info := n.mustTx(t, tx.ID()); info.Status != StatusQueued {
354				t.Fatalf("queued-only tx %q status = %s, want queued after rejected registers", tx.Content, info.Status)
355			}
356		}
357		for _, tx := range []*Transaction{sc.a3, sc.a4, sc.b2, sc.c1, sc.c2} {
358			if info := n.mustTx(t, tx.ID()); info.Status != StatusProposed {
359				t.Fatalf("referenced tx %q status = %s, want proposed after rejected registers", tx.Content, info.Status)
360			}
361		}
362	
363		// 排队交易 b3 没有被失败登记锁定：同发送者同序号、费用严格更高仍可替换。
364		b3hi := NewTransaction(keys[1].priv, 3, []byte("b3-hi"), 99, 100)
365		rep, err := n.Submit(b3hi)
366		if err != nil {
367			t.Fatalf("queued-only b3 must stay replaceable after rejected registers: %v", err)
368		}
369		if rep.ReplacedID != sc.b3.ID() {
370			t.Fatalf("replacement result = %+v, want ReplacedID %s", rep, sc.b3.ID())
371		}
372		if info := n.mustTx(t, sc.b3.ID()); info.Status != StatusReplaced || info.ReplacedBy != b3hi.ID() {
373			t.Fatalf("b3 after replacement = %+v, want replaced by %s", info, b3hi.ID())
374		}
375		// 已被候选引用的 a3 继续锁定：加费替换仍以 tx-in-proposal 拒绝。
376		a3hi := NewTransaction(keys[0].priv, 3, []byte("a3-hi"), 99, 100)
377		if _, err := n.Submit(a3hi); reason(err) != ReasonProposalLocked {
378			t.Fatalf("referenced a3 must stay locked, got %v, want %s", err, ReasonProposalLocked)
379		}
380	}
381

