120		txSeq.Sequence++
121		if txSeq.Verify() {
122			t.Fatal("tampered sequence must fail verification")
123		}
124		// 不同费用产生不同标识。
125		tx3 := NewTransaction(keys[0].priv, 7, []byte("hello"), 4, 99)
126		if tx3.ID() == id1 {
127			t.Fatal("different fee must yield different id")
128		}
