1	package consensus
2	
3	import (
4		"fmt"
5		"testing"
6	)
7	
8	// 本文件保障 Submit 的“提交输入独立性”：节点接受一笔已签名交易后，
9	// 调用方继续持有并修改原来的 *Transaction，节点接受的始终是提交成功时的内容。
10	// 与 query_copy_test.go 的查询结果副本保障分别守住出入口两侧：
11	// 提交入口拷贝输入，查询出口拷贝内部对象。
12	//
13	// 两类调用方编辑都要覆盖：
14	//   - 原地改写（in-place）：直接改原对象中的公钥、内容、签名字节与标量字段；
15	//   - 整体替换（replace）：把原对象中的这些字段换成另一份值/另一个数组。
16	// 两种编辑都只能改变调用方手中的对象，不能反过来改写池内交易。
17	
18	// replaceAllFields 把原对象里的字段“换成另一份值”：Sender/Content/Signature
19	// 指向全新分配的数组（而非在原底层数组上改写），标量字段一并替换。
20	func replaceAllFields(tx *Transaction, sender, content, signature []byte, sequence, fee, expiry uint64) {
21		tx.Sender = append([]byte(nil), sender...)
22		tx.Content = append([]byte(nil), content...)
23		tx.Signature = append([]byte(nil), signature...)
24		tx.Sequence = sequence
25		tx.Fee = fee
26		tx.Expiry = expiry
27	}
28	
29	// assertPendingAt 断言某账户当前恰有一笔序号为 seq、标识为 id 的待处理交易，
30	// 且其等待说明与给定状态相符；同时确认已确认序号与最早缺口序号。
31	func assertPendingAt(t *testing.T, n *Node, key testKey, confirmed, gap uint64, id, note string) {
32		t.Helper()
33		acct := n.Account(key.pub)
34		if acct.ConfirmedSequence != confirmed || acct.Gap != gap || len(acct.Pending) != 1 {
35			t.Fatalf("account %x = {confirmed:%d gap:%d pending:%d}, want {confirmed:%d gap:%d pending:1}",
36				key.pub, acct.ConfirmedSequence, acct.Gap, len(acct.Pending), confirmed, gap)
37		}
38		got := acct.Pending[0]
39		if got.ID != id || got.Note != note {
40			t.Fatalf("pending entry = {id:%s note:%s}, want {id:%s note:%s}", got.ID, got.Note, id, note)
41		}
42	}
43	
44	// submitAndSnapshot 提交交易并返回提交成功时的独立快照，供事后与节点状态比对，
45	// 避免直接保留原对象指针——调用方随后会故意改写原对象。
46	func submitAndSnapshot(t *testing.T, n *Node, tx *Transaction) (*Transaction, string) {
47		t.Helper()
48		res, err := n.Submit(tx)
49		if err != nil {
50			t.Fatalf("submit failed: %v", err)
51		}
52		saved := copyTx(tx)
53		if res.TxID != saved.ID() {
54			t.Fatalf("submit returned id %s, want %s", res.TxID, saved.ID())
55		}
56		return saved, res.TxID
57	}
58	
59	// 成功提交后，无论调用方在原对象上原地改写还是整体替换发送者公钥、序号、内容、
60	// 费用、到期轮次与签名字节，按提交返回标识查到的始终是接受时的完整交易：
61	// 标识与完整交易相符，签名仍有效；交易仍列在原发送者名下、保持原序号与缺口说明，
62	// 既不会搬到另一个账户，也不会凭空产生第二条待处理记录。
63	func TestSubmitInputIsIndependentCopy(t *testing.T) {
64		keys := genKeys(t, 4)
65		n, _ := newTestNode(t, keys, 10)
66	
67		// 调用方提交后继续持有原来的对象指针，提交成功时留一份独立快照作比对基准。
68		callerTx := NewTransaction(keys[0].priv, 1, []byte("payload"), 4, 100)
69		original, id := submitAndSnapshot(t, n, callerTx)
70	
71		// 账户初始形态：原发送者名下一笔序号 1 的待处理交易，无缺口。
72		assertPendingAt(t, n, keys[0], 0, 0, id, "waiting-pack")
73		otherAcct := n.Account(keys[1].pub)
74		if otherAcct.ConfirmedSequence != 0 || otherAcct.Gap != 0 || len(otherAcct.Pending) != 0 {
75			t.Fatalf("unrelated account must be empty before tamper: %+v", otherAcct)
76		}
77	
78		// 第一类编辑：在原对象上原地改写公钥、内容、签名字节（原底层数组被改），
79		// 并改序号、费用、到期轮次。
80		callerTx.Sender[0] ^= 0xff
81		callerTx.Content = append(callerTx.Content, "-in-place"...)
82		callerTx.Signature[0] ^= 0xff
83		callerTx.Sequence = 9
84		callerTx.Fee = 777
85		callerTx.Expiry = 1 // 改为当前轮次，试图让交易立即到期
86	
87		got, err := n.Tx(id)
88		if err != nil {
89			t.Fatal(err)
90		}
91		if got.Status != StatusQueued {
92			t.Fatalf("status after in-place edit = %s, want %s", got.Status, StatusQueued)
93		}
94		assertTxMatches(t, got.Tx, original)
95		// 交易没有搬到“被改成的公钥”名下，也没有出现第二条待处理记录。
96		assertPendingAt(t, n, keys[0], 0, 0, id, "waiting-pack")
97		if acct := n.Account(callerTx.Sender); len(acct.Pending) != 0 {
98			t.Fatalf("in-place sender edit created a pending record under another account: %+v", acct.Pending)
99		}
100		if acct := n.Account(keys[1].pub); len(acct.Pending) != 0 {
101			t.Fatalf("unrelated account must stay empty: %+v", acct.Pending)
102		}
103	
104		// 第二类编辑：把这些字段整体换成另一份值（新数组、新标量）。
105		replaceAllFields(callerTx,
106			append([]byte(nil), keys[1].pub...),
107			[]byte("whole-replacement"),
108			append([]byte(nil), original.Signature...), // 先换成原签名的另一份拷贝……
109			42, 1, 5)
110		callerTx.Signature[0] ^= 0xaa // ……再破坏这份拷贝，原签名数组不受影响。
111	
112		got2, err := n.Tx(id)
113		if err != nil {
114			t.Fatal(err)
115		}
116		assertTxMatches(t, got2.Tx, original)
117		assertPendingAt(t, n, keys[0], 0, 0, id, "waiting-pack")
118		if acct := n.Account(keys[1].pub); len(acct.Pending) != 0 {
119			t.Fatalf("replaced sender edit moved the tx to another account: %+v", acct.Pending)
120		}
121		// 篡改出来的标识没有成为节点中的另一笔交易。
122		if _, err := n.Tx(callerTx.ID()); reason(err) != ReasonUnknownTx {
123			t.Fatalf("tampered id got %v, want %s", err, ReasonUnknownTx)
124		}
125	}
