127	// 序号缺口同样只按提交时的序号记录：提交一笔越过缺口的高序号交易后，
128	// 调用方把原对象序号改成缺口序号或更大的序号，账户的缺口说明与待处理记录不变。
129	func TestSubmitInputSequenceGapUnaffected(t *testing.T) {
130		keys := genKeys(t, 4)
131		n, _ := newTestNode(t, keys, 10)
132	
133		// 只提交序号 3：最早缺口序号为 1。
134		callerTx := NewTransaction(keys[0].priv, 3, []byte("gappy"), 2, 100)
135		original, id := submitAndSnapshot(t, n, callerTx)
136	
137		acct := n.Account(keys[0].pub)
138		if acct.ConfirmedSequence != 0 || acct.Gap != 1 || len(acct.Pending) != 1 || acct.Pending[0].ID != id {
139			t.Fatalf("setup account wrong: %+v", acct)
140		}
141	
142		// 原地把序号改成缺口序号 1：不能凭空补上缺口，也不能让原交易越过缺口可打包。
143		callerTx.Sequence = 1
144		again := n.Account(keys[0].pub)
145		if again.Gap != 1 || len(again.Pending) != 1 || again.Pending[0].Tx.Sequence != 3 || again.Pending[0].ID != id {
146			t.Fatalf("in-place sequence edit leaked into account: %+v", again)
147		}
148		info, _ := n.Tx(id)
149		assertTxMatches(t, info.Tx, original)
150	
151		// 整体替换成更大的序号 99：缺口与待处理记录仍是提交时的样子。
152		replaceAllFields(callerTx, append([]byte(nil), keys[0].pub...),
153			[]byte("gappy"), append([]byte(nil), original.Signature...), 99, 2, 100)
154		again2 := n.Account(keys[0].pub)
155		if again2.Gap != 1 || len(again2.Pending) != 1 || again2.Pending[0].Tx.Sequence != 3 {
156			t.Fatalf("replaced sequence edit leaked into account: %+v", again2)
157		}
158	
159		// 节点仍认为序号 1、2 缺失：空块提议证明高序号交易无法越过缺口被打包。
160		p, err := n.Propose()
161		if err != nil {
162			t.Fatal(err)
163		}
164		if len(p.TxIDs) != 0 {
165			t.Fatalf("tx must not cross the sequence gap after caller edit: %v", p.TxIDs)
166		}
167	}
