169	// 事后提高或降低输入对象的费用，不能改变原先由费用与交易标识决定的打包顺序。
170	// 原交易与其他账户的交易一起排队时，提议冻结的顺序始终是提交时费用对应的顺序。
171	func TestSubmitInputFeeEditsDoNotChangePackingOrder(t *testing.T) {
172		keys := genKeys(t, 4)
173	
174		// 原交易 txA 费用 3、txB 费用 7：打包顺序固定为 [txB, txA]。
175		setup := func() (*Node, *Transaction, *Transaction, *Transaction, string, string) {
176			n, _ := newTestNode(t, keys, 10)
177			callerA := NewTransaction(keys[0].priv, 1, []byte("alpha"), 3, 100)
178			txB := NewTransaction(keys[1].priv, 1, []byte("beta"), 7, 100)
179			origA, idA := submitAndSnapshot(t, n, callerA)
180			if _, err := n.Submit(txB); err != nil {
181				t.Fatal(err)
182			}
183			return n, callerA, txB, origA, idA, txB.ID()
184		}
185	
186		t.Run("raise fee in place cannot jump the queue", func(t *testing.T) {
187			n, callerA, _, origA, idA, idB := setup()
188			callerA.Fee = 1000 // 原地把费用抬到最高。
189			callerA.Content = append(callerA.Content, "!"...)
190			callerA.Signature[0] ^= 0xff
191			p, err := n.Propose()
192			if err != nil {
193				t.Fatal(err)
194			}
195			if fmt.Sprint(p.TxIDs) != fmt.Sprint([]string{idB, idA}) {
196				t.Fatalf("packing order changed by in-place fee raise: %v", p.TxIDs)
197			}
198			info, _ := n.Tx(idA)
199			assertTxMatches(t, info.Tx, origA)
200		})
201	
202		t.Run("lower fee by replacement cannot sink the tx", func(t *testing.T) {
203			n, callerA, _, origA, idA, idB := setup()
204			// 整体替换：费用降为 0，内容与签名换成另一份数组。
205			replaceAllFields(callerA, append([]byte(nil), origA.Sender...),
206				[]byte("alpha-cheap"), make([]byte, 64), 1, 0, 100)
207			p, err := n.Propose()
208			if err != nil {
209				t.Fatal(err)
210			}
211			if fmt.Sprint(p.TxIDs) != fmt.Sprint([]string{idB, idA}) {
212				t.Fatalf("packing order changed by replaced fee lower: %v", p.TxIDs)
213			}
214			info, _ := n.Tx(idA)
215			assertTxMatches(t, info.Tx, origA)
216		})
217	}
