219	// 事后改动输入对象的到期轮次，不能让原交易提前失效，也不能延长其有效期。
220	// 节点始终按提交时的到期轮次在进入新轮次时失效该交易。
221	func TestSubmitInputExpiryEditsDoNotChangeLifetime(t *testing.T) {
222		keys := genKeys(t, 4)
223	
224		// 原交易到期轮次 3：第 2 轮仍有效，进入第 3 轮失效。
225		t.Run("shrinking expiry in place must not expire it early", func(t *testing.T) {
226			n, _ := newTestNode(t, keys, 10)
227			callerTx := NewTransaction(keys[0].priv, 1, []byte("exp"), 1, 3)
228			original, id := submitAndSnapshot(t, n, callerTx)
229	
230			callerTx.Expiry = 1 // 原地改为当前轮次，试图让交易立即到期。
231			callerTx.Signature[0] ^= 0xff
232			// 结束第 1 轮进入第 2 轮：按提交时的到期轮次 3，交易仍有效并回到排队。
233			if _, err := n.EndRound(); err != nil {
234				t.Fatal(err)
235			}
236			info, err := n.Tx(id)
237			if err != nil {
238				t.Fatal(err)
239			}
240			if info.Status != StatusQueued {
241				t.Fatalf("tx expired early from in-place expiry edit: status = %s, want queued", info.Status)
242			}
243			assertTxMatches(t, info.Tx, original)
244			p, err := n.Propose()
245			if err != nil {
246				t.Fatal(err)
247			}
248			if fmt.Sprint(p.TxIDs) != fmt.Sprint([]string{id}) {
249				t.Fatalf("valid tx must still pack in round 2: %v", p.TxIDs)
250			}
251	
252			// 结束第 2 轮进入第 3 轮：交易按原到期轮次失效，篡改不能延长有效期。
253			if _, err := n.EndRound(); err != nil {
254				t.Fatal(err)
255			}
256			expired, err := n.Tx(id)
257			if err != nil {
258				t.Fatal(err)
259			}
260			if expired.Status != StatusExpired {
261				t.Fatalf("status = %s, want expired at round 3", expired.Status)
262			}
263			assertTxMatches(t, expired.Tx, original)
264			if acct := n.Account(keys[0].pub); len(acct.Pending) != 0 {
265				t.Fatalf("expired tx must leave pending: %+v", acct.Pending)
266			}
267		})
268	
269		t.Run("extending expiry by replacement must not keep it alive", func(t *testing.T) {
270			n, _ := newTestNode(t, keys, 10)
271			callerTx := NewTransaction(keys[0].priv, 1, []byte("exp"), 1, 3)
272			original, id := submitAndSnapshot(t, n, callerTx)
273	
274			// 整体替换：到期轮次延长到 1000，签名换成另一份数组。
275			replaceAllFields(callerTx, append([]byte(nil), original.Sender...),
276				append([]byte(nil), original.Content...), make([]byte, 64), 1, 1, 1000)
277			if _, err := n.EndRound(); err != nil {
278				t.Fatal(err)
279			}
280			if _, err := n.EndRound(); err != nil {
281				t.Fatal(err)
282			}
283			info, err := n.Tx(id)
284			if err != nil {
285				t.Fatal(err)
286			}
287			if info.Status != StatusExpired {
288				t.Fatalf("tx lifetime extended by caller replacement: status = %s, want expired", info.Status)
289			}
290			assertTxMatches(t, info.Tx, original)
291		})
292	}
