294	// 对原本能够打包且尚未到期的交易，事后修改输入对象不影响后续打包与确认：
295	// 确认块包含的仍是提交返回的原标识，交易查询关联实际确认的区块，
296	// 账户已确认序号按原交易推进；序号连续、单块上限与投票确认规则保持不变。
297	func TestSubmitInputEditsSurviveThroughConfirmation(t *testing.T) {
298		keys := genKeys(t, 4)
299		n, dir := newTestNode(t, keys, 10)
300	
301		// 账户甲序号 1、2 连续两笔，账户乙一笔参与同块；上限充足可同块打包。
302		callerA1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 2, 100)
303		callerA2 := NewTransaction(keys[0].priv, 2, []byte("a2"), 8, 100)
304		txB1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 5, 100)
305		origA1, idA1 := submitAndSnapshot(t, n, callerA1)
306		origA2, idA2 := submitAndSnapshot(t, n, callerA2)
307		if _, err := n.Submit(txB1); err != nil {
308			t.Fatal(err)
309		}
310		idB1 := txB1.ID()
311	
312		// 提交成功后尽力改写甲手中的两个原对象（原地 + 整体替换两种手法）。
313		callerA1.Sender[0] ^= 0xff
314		callerA1.Content = append(callerA1.Content, "-x"...)
315		callerA1.Signature[0] ^= 0xff
316		callerA1.Fee = 9999 // 试图抬高费用插到最前
317		callerA1.Sequence = 3
318		callerA1.Expiry = 1
319		replaceAllFields(callerA2, append([]byte(nil), keys[2].pub...),
320			[]byte("a2-replaced"), make([]byte, 64), 77, 0, 1)
321	
322		// 打包顺序只由提交时的费用、标识与序号连续规则决定：首轮各账户下一条中
323		// b1(5) 先于 a1(2)，a1 入选后 a2(8) 才具备条件，顺序固定为 [b1, a1, a2]；
324		// 调用方把 a1 费用改成 9999 也不能让它插队，单块上限与序号连续规则照常生效。
325		p, err := n.Propose()
326		if err != nil {
327			t.Fatal(err)
328		}
329		want := []string{idB1, idA1, idA2}
330		if fmt.Sprint(p.TxIDs) != fmt.Sprint(want) {
331			t.Fatalf("proposal order = %v, want %v (caller edits must not leak)", p.TxIDs, want)
332		}
333		if wantID := BlockID(1, 1, "", want); p.BlockID != wantID {
334			t.Fatalf("block id = %s, want %s", p.BlockID, wantID)
335		}
336	
337		// 投票确认规则不变：3/4 票严格超过 2/3 立即确认。
338		confirmByVotes(t, n, keys, p.BlockID)
339	
340		// 确认块包含的仍是提交返回的原标识，交易查询关联实际确认的区块。
341		blk, err := n.BlockAt(1)
342		if err != nil {
343			t.Fatal(err)
344		}
345		if fmt.Sprint(blk.TxIDs) != fmt.Sprint(want) || blk.ID != p.BlockID || blk.Height != 1 || blk.Round != 1 {
346			t.Fatalf("confirmed block wrong: %+v", blk)
347		}
348		for _, id := range want {
349			info, err := n.Tx(id)
350			if err != nil {
351				t.Fatal(err)
352			}
353			if info.Status != StatusConfirmed || info.BlockHeight != 1 || info.BlockID != p.BlockID {
354				t.Fatalf("confirmed tx %s lookup wrong: %+v", id, info)
355			}
356		}
357		assertTxMatches(t, n.mustTx(t, idA1).Tx, origA1)
358		assertTxMatches(t, n.mustTx(t, idA2).Tx, origA2)
359	
360		// 账户已确认序号按原交易推进到 2；乙推进到 1；被改成的“另一个账户”一无所有。
361		if acct := n.Account(keys[0].pub); acct.ConfirmedSequence != 2 || len(acct.Pending) != 0 {
362			t.Fatalf("sender A account wrong after confirm: %+v", acct)
363		}
364		if acct := n.Account(keys[1].pub); acct.ConfirmedSequence != 1 || len(acct.Pending) != 0 {
365			t.Fatalf("sender B account wrong after confirm: %+v", acct)
366		}
367		if acct := n.Account(keys[2].pub); acct.ConfirmedSequence != 0 || len(acct.Pending) != 0 {
368			t.Fatalf("edits must not create state under the replaced sender: %+v", acct)
369		}
370	
371		// 篡改不随正常保存落盘：重开后确认历史与账户推进仍是接受时的交易。
372		reopened, err := Open(dir)
373		if err != nil {
374			t.Fatal(err)
375		}
376		storedBlk, err := reopened.BlockAt(1)
377		if err != nil {
378			t.Fatal(err)
379		}
380		if fmt.Sprint(storedBlk.TxIDs) != fmt.Sprint(want) || storedBlk.ID != p.BlockID {
381			t.Fatalf("confirmed history changed after reopen: %+v", storedBlk)
382		}
383		info, err := reopened.Tx(idA1)
384		if err != nil {
385			t.Fatal(err)
386		}
387		assertTxMatches(t, info.Tx, origA1)
388		if acct := reopened.Account(keys[0].pub); acct.ConfirmedSequence != 2 {
389			t.Fatalf("confirmed sequence after reopen = %d, want 2", acct.ConfirmedSequence)
390		}
391	}
