393	// mustTx 按标识查询，失败即终止测试。
394	func (n *Node) mustTx(t *testing.T, id string) *TxInfo {
395		t.Helper()
396		info, err := n.Tx(id)
397		if err != nil {
398			t.Fatalf("tx %s: %v", id, err)
399		}
400		return info
401	}
