403	// 空内容同样是合法交易。提交成功后再给原对象填入内容，节点中保留原来的
404	// 空内容、标识与有效签名；整体替换 Content 数组同样只影响调用方手中的对象。
405	func TestSubmitEmptyContentInputStaysIntact(t *testing.T) {
406		keys := genKeys(t, 4)
407		n, dir := newTestNode(t, keys, 10)
408	
409		callerTx := NewTransaction(keys[0].priv, 1, nil, 2, 100)
410		original, id := submitAndSnapshot(t, n, callerTx)
411		if len(original.Content) != 0 {
412			t.Fatal("setup: content must be empty")
413		}
414	
415		info, err := n.Tx(id)
416		if err != nil {
417			t.Fatal(err)
418		}
419		if info.ID != id || len(info.Tx.Content) != 0 {
420			t.Fatalf("empty-content accepted tx wrong: %+v", info)
421		}
422		assertTxMatches(t, info.Tx, original)
423	
424		// 原地给原对象填入内容（Content 由 nil 变为有字节）。
425		callerTx.Content = append(callerTx.Content, []byte("filled-by-caller")...)
426		got, err := n.Tx(id)
427		if err != nil {
428			t.Fatal(err)
429		}
430		if len(got.Tx.Content) != 0 || got.ID != id {
431			t.Fatalf("in-place fill leaked into node: %+v", got)
432		}
433		assertTxMatches(t, got.Tx, original)
434	
435		// 整体替换 Content 为另一份非空数组。
436		callerTx.Content = append([]byte(nil), []byte("replaced-content")...)
437		callerTx.Signature[0] ^= 0xff
438		got2, err := n.Tx(id)
439		if err != nil {
440			t.Fatal(err)
441		}
442		if len(got2.Tx.Content) != 0 {
443			t.Fatalf("replaced content leaked into node: %q", got2.Tx.Content)
444		}
445		assertTxMatches(t, got2.Tx, original)
446		if acct := n.Account(keys[0].pub); len(acct.Pending) != 1 || acct.Pending[0].ID != id || len(acct.Pending[0].Tx.Content) != 0 {
447			t.Fatalf("account pending changed by fill: %+v", acct.Pending)
448		}
449	
450		// 空内容交易仍可正常打包与确认，确认块与查询都指向原空内容交易。
451		p, err := n.Propose()
452		if err != nil {
453			t.Fatal(err)
454		}
455		if fmt.Sprint(p.TxIDs) != fmt.Sprint([]string{id}) {
456			t.Fatalf("empty-content tx proposal wrong: %v", p.TxIDs)
457		}
458		confirmByVotes(t, n, keys, p.BlockID)
459		confirmed, err := n.Tx(id)
460		if err != nil {
461			t.Fatal(err)
462		}
463		if confirmed.Status != StatusConfirmed || confirmed.BlockID != p.BlockID || len(confirmed.Tx.Content) != 0 {
464			t.Fatalf("empty-content tx confirm wrong: %+v", confirmed)
465		}
466		assertTxMatches(t, confirmed.Tx, original)
467	
468		// 重开后仍是那笔空内容交易。
469		reopened, err := Open(dir)
470		if err != nil {
471			t.Fatal(err)
472		}
473		stored, err := reopened.Tx(id)
474		if err != nil {
475			t.Fatal(err)
476		}
477		if len(stored.Tx.Content) != 0 || stored.Status != StatusConfirmed {
478			t.Fatalf("empty-content tx changed after reopen: %+v", stored)
479		}
480		assertTxMatches(t, stored.Tx, original)
481	}
482	
483	// 调用方把修改过、签名已经不匹配的对象再次提交，必须按现有规则以
484	// bad-signature 拒绝；之前接受的交易及其查询结果保持原样，拒绝不产生第二条记录。
485	func TestResubmitTamperedInputRejectedBadSignature(t *testing.T) {
486		keys := genKeys(t, 4)
487		n, _ := newTestNode(t, keys, 10)
488	
489		callerTx := NewTransaction(keys[0].priv, 1, []byte("once"), 3, 100)
490		original, id := submitAndSnapshot(t, n, callerTx)
491	
492		t.Run("in-place tamper then resubmit", func(t *testing.T) {
493			// 只改内容：签名不再覆盖新内容，验签失败。
494			callerTx.Content = append(callerTx.Content, "-tampered"...)
495			if _, err := n.Submit(callerTx); reason(err) != ReasonBadSignature {
496				t.Fatalf("resubmit tampered content got %v, want %s", err, ReasonBadSignature)
497			}
498			// 只改费用：签名覆盖费用，同样验签失败（不会走到 fee-not-higher）。
499			callerTx.Content = append([]byte(nil), original.Content...)
500			callerTx.Fee = original.Fee + 1
501			if _, err := n.Submit(callerTx); reason(err) != ReasonBadSignature {
502				t.Fatalf("resubmit tampered fee got %v, want %s", err, ReasonBadSignature)
503			}
504		})
505	
506		t.Run("whole-replacement tamper then resubmit", func(t *testing.T) {
507			// 换成另一账户的公钥但保留原签名：签名对新公钥无效，按 bad-signature 拒绝，
508			// 而不是被当作另一账户的新交易接受。
509			replaceAllFields(callerTx, append([]byte(nil), keys[1].pub...),
510				append([]byte(nil), original.Content...),
511				append([]byte(nil), original.Signature...),
512				original.Sequence, original.Fee, original.Expiry)
513			if _, err := n.Submit(callerTx); reason(err) != ReasonBadSignature {
514				t.Fatalf("resubmit with replaced sender got %v, want %s", err, ReasonBadSignature)
515			}
516		})
517	
518		// 之前接受的交易及其查询结果保持原样。
519		info, err := n.Tx(id)
520		if err != nil {
521			t.Fatal(err)
522		}
523		if info.Status != StatusQueued {
524			t.Fatalf("original tx status = %s, want queued after rejected resubmits", info.Status)
525		}
526		assertTxMatches(t, info.Tx, original)
527		// 没有产生第二条待处理记录，也没有搬到其他账户。
528		assertPendingAt(t, n, keys[0], 0, 0, id, "waiting-pack")
529		if acct := n.Account(keys[1].pub); len(acct.Pending) != 0 {
530			t.Fatalf("rejected resubmit created a pending record: %+v", acct.Pending)
531		}
532	
533		// 用原私钥重新签发“加费替换”是合法的现有行为：新交易被接受、旧交易标记
534		// replaced，证明前面的拒绝纯粹来自签名规则，提交入口的兼容语义没有改变。
535		replacement := NewTransaction(keys[0].priv, 1, []byte("once-bumped"), original.Fee+1, 100)
536		res, err := n.Submit(replacement)
537		if err != nil {
538			t.Fatalf("properly signed higher-fee replacement should be accepted: %v", err)
539		}
540		if res.ReplacedID != id {
541			t.Fatalf("replacement replaced id = %q, want %s", res.ReplacedID, id)
542		}
543		old, err := n.Tx(id)
544		if err != nil {
545			t.Fatal(err)
546		}
547		if old.Status != StatusReplaced || old.ReplacedBy != res.TxID {
548			t.Fatalf("original tx after valid replacement = %+v, want replaced by %s", old, res.TxID)
549		}
550		assertTxMatches(t, old.Tx, original)
551	}
552	
553	// 提交入口本身必须完成输入与内部存储的剥离，而不能依赖后续 Propose/Vote 的
554	// clone 兜底：成功提交后立即检查内部 Entries 中的交易，其指针与三个字节切片
555	// 都不与调用方对象共享底层数组；调用方随后在原对象上的任何编辑，到达内部
556	// 对象的路径必须全部被切断。
557	func TestSubmitDetachesInternalEntryFromCallerInput(t *testing.T) {
558		keys := genKeys(t, 4)
559		n, _ := newTestNode(t, keys, 10)
560	
561		callerTx := NewTransaction(keys[0].priv, 1, []byte("detach"), 6, 100)
562		res, err := n.Submit(callerTx)
563		if err != nil {
564			t.Fatal(err)
565		}
566		stored := n.st.Entries[res.TxID].Tx
567		if stored == callerTx {
568			t.Fatal("Submit must store a distinct Transaction, not the caller's pointer")
569		}
570		// 三个字节切片都必须拥有独立底层数组：比较首元素地址即可识别别名。
571		if len(callerTx.Sender) > 0 && &stored.Sender[0] == &callerTx.Sender[0] {
572			t.Fatal("stored Sender shares backing array with caller input")
573		}
574		if len(callerTx.Content) > 0 && &stored.Content[0] == &callerTx.Content[0] {
575			t.Fatal("stored Content shares backing array with caller input")
576		}
577		if len(callerTx.Signature) > 0 && &stored.Signature[0] == &callerTx.Signature[0] {
578			t.Fatal("stored Signature shares backing array with caller input")
579		}
580		assertTxMatches(t, stored, callerTx)
581	}
